{
  "passageId": "plastic-polymerization",
  "items": [
    {
      "id": "R1",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "어원의 의미와 고분자 화합물이라는 설명을 통해 플라스틱이라는 말의 뜻을 풀이한다."
    },
    {
      "id": "R2",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "플라스틱의 형성 방식으로 제시된 ‘중합’이 무엇을 뜻하는지 풀이한다."
    },
    {
      "id": "R3",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "단위체를 연결하는 ‘공유 결합’이라는 용어의 뜻을 풀이한다."
    },
    {
      "id": "R4",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "공유하는 전자쌍의 수라는 동일한 기준에서 단일 결합과 이중 결합의 차이를 제시한다."
    },
    {
      "id": "R5",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "단일 결합과 이중 결합에 관한 일반 설명을 에틸렌의 분자 구조에 적용한다."
    },
    {
      "id": "R6",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "바깥 전자 껍질의 전자 수와 안정성에 관한 일반 원리를 탄소 원자에 적용한다."
    },
    {
      "id": "R7",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "탄소의 바깥 껍질 전자가 4개라는 사실이 전자 공유를 통해 안정해질 수 있다는 설명을 뒷받침한다."
    },
    {
      "id": "R8",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "다양한 공유 결합이 가능하다는 성질을 근거로 탄소가 거대 분자의 골격을 이룰 수 있다고 설명한다."
    },
    {
      "id": "R9",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "중합으로 형성되는 플라스틱의 일반적 설명을 폴리에틸렌이라는 구체적 사례로 보여 준다."
    },
    {
      "id": "R10",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "에틸렌의 탄소 간 이중 결합을 이루는 두 결합의 특성을 더 자세히 설명한다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "이중 결합 중 하나가 더 쉽게 끊어진다는 성질이 개시 반응에서 그 결합이 끊어지는 이유를 뒷받침한다."
    },
    {
      "id": "R12",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "에틸렌의 중합이라는 설명을 과산화물 개시제를 사용하는 구체적 반응 과정으로 풀어 준다."
    },
    {
      "id": "R13",
      "type": "CAUSE",
      "otherName": "",
      "reason": "개시제 분해로 생긴 원자의 불안정성이 안정해지기 위한 에틸렌과의 결합 반응으로 이어진다."
    },
    {
      "id": "R14",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "전자 수에 따른 원자의 안정성 원리를 개시제 분해로 생긴 전자 7개의 원자에 적용한다."
    },
    {
      "id": "R15",
      "type": "CAUSE",
      "otherName": "",
      "reason": "이중 결합이 끊어지고 한쪽 탄소가 새 결합을 형성하는 반응이 다른 쪽 탄소에 홀전자를 남긴다."
    },
    {
      "id": "R16",
      "type": "CAUSE",
      "otherName": "",
      "reason": "홀전자를 가진 탄소의 불안정성이 다른 에틸렌 분자와의 후속 반응으로 이어진다."
    },
    {
      "id": "R17",
      "type": "CAUSE",
      "otherName": "",
      "reason": "에틸렌과의 반응이 반복되면서 새로운 불안정한 탄소 원자가 계속 생성된다."
    },
    {
      "id": "R18",
      "type": "CAUSE",
      "otherName": "",
      "reason": "새로운 불안정한 탄소를 만드는 반복 반응이 에틸렌 사슬의 지속적인 성장을 일으킨다."
    },
    {
      "id": "R19",
      "type": "CAUSE",
      "otherName": "",
      "reason": "두 사슬 끝의 결합으로 불안정성이 해소되어 반복 반응이 멈춘다."
    },
    {
      "id": "R20",
      "type": "PROCESS",
      "otherName": "",
      "reason": "중합 과정에서 사슬이 성장하는 단계 다음에 두 사슬의 결합으로 반응이 종결되는 단계가 이어진다."
    },
    {
      "id": "R21",
      "type": "PROCESS",
      "otherName": "",
      "reason": "사슬의 성장과 종결을 거친 중합 과정이 최종 산물인 폴리에틸렌의 형성으로 마무리된다."
    },
    {
      "id": "R22",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "중합 중 사슬이 성장하는 과정에서 완성된 플라스틱 분자의 길이와 구조적 성질로 논의가 옮겨 간다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "분자의 길이가 길다는 사실을 근거로 전체가 아닌 일부에서만 결정 영역을 기대할 수 있다고 설명한다."
    },
    {
      "id": "R24",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "결정 영역 비율이 물성에 영향을 준다는 설명을 개별 물성의 변화 방향으로 구체화한다."
    },
    {
      "id": "R25",
      "type": "CAUSE",
      "otherName": "",
      "reason": "플라스틱의 유연성 감소가 충격에 약해지는 결과를 일으킨다."
    },
    {
      "id": "R26",
      "type": "CAUSE",
      "otherName": "",
      "reason": "플라스틱의 밀도 증가가 단단해지는 결과로 이어진다."
    },
    {
      "id": "R27",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "하나의 플라스틱에서 결정 영역 증가가 유연성 등의 저하와 단단함 등의 향상이라는 양면적 변화를 낳음을 제시한다."
    },
    {
      "id": "R28",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "결정 영역 비율에 따른 성질 변화를 활용하는 것이 필요에 맞는 플라스틱을 만드는 수단이 된다."
    },
    {
      "id": "R29",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "결정 영역 비율을 조절할 수 있다는 사실이 필요에 맞는 다양한 플라스틱을 만들 수 있다는 판단을 뒷받침한다."
    }
  ]
}

